prompt --application/shared_components/security/authorizations/audit_administrator
begin
wwv_flow_imp_shared.create_security_scheme(
 p_id=>wwv_flow_imp.id(5505069898560897)
,p_name=>'Audit Administrator'
,p_static_id=>'audit-administrator'
,p_scheme_type=>'NATIVE_FUNCTION_BODY'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'plsql_function_body', wwv_flow_string.join(wwv_flow_t_varchar2(
    '-- Workspace administrators and developers may change auditing,',
    '-- restore rows and purge history. Everyone else is read-only.',
    'for u in (',
    '    select 1',
    '    from apex_workspace_apex_users',
    '    where workspace_name = apex_util.find_workspace(apex_application.get_security_group_id)',
    '      and user_name = upper(:APP_USER)',
    '      and (is_admin = ''Yes'' or is_application_developer = ''Yes'')',
    ') loop',
    '    return true;',
    'end loop;',
    'return false;')))).to_clob
,p_error_message=>'Only workspace administrators and developers can change auditing.'
,p_caching=>'BY_USER_BY_SESSION'
);
end;
