wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(5519035050561002)
,p_name=>'Column Changes'
,p_static_id=>'column-changes'
,p_template=>4073835273271169698
,p_display_sequence=>30
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--horizontalBorders'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select r.column_name,',
'       r.data_type,',
'       coalesce(r.old_value, dbms_lob.substr(r.old_clob, 1000, 1)) old_value,',
'       coalesce(r.new_value, dbms_lob.substr(r.new_clob, 1000, 1)) new_value',
'from util_audit_records r',
'left join user_tab_columns c',
'  on c.table_name = r.table_name',
' and c.column_name = r.column_name',
'where r.transaction_id = :P5_TRANSACTION_ID',
'order by c.column_id nulls last, r.column_name'))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>2540130677583398057
,p_query_num_rows=>200
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_no_data_found=>'No column changes recorded.'
