wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(5518763721561002)
,p_name=>'Context'
,p_static_id=>'context'
,p_template=>4073835273271169698
,p_display_sequence=>20
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--horizontalBorders'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select key_label,',
'       value',
'from (',
'    select j.*',
'    from util_audit_txn t,',
'         json_table(t.audit_context, ''$''',
'             columns (',
'                 app_id     varchar2(4000) path ''$.app_id'',',
'                 page_id    varchar2(4000) path ''$.page_id'',',
'                 session_id varchar2(4000) path ''$.session_id'',',
'                 module     varchar2(4000) path ''$.module'',',
'                 client_id  varchar2(4000) path ''$.client_id'',',
'                 action     varchar2(4000) path ''$.action'',',
'                 ip         varchar2(4000) path ''$.ip'',',
'                 host       varchar2(4000) path ''$.host'',',
'                 os_user    varchar2(4000) path ''$.os_user'',',
'                 app_user   varchar2(4000) path ''$.app_user'',',
'                 schema     varchar2(4000) path ''$.schema''',
'             )) j',
'    where t.transaction_id = :P5_TRANSACTION_ID',
')',
'unpivot exclude nulls (',
'    value for key_label in (',
'        app_id     as ''APEX App'',',
'        page_id    as ''APEX Page'',',
'        session_id as ''APEX Session'',',
'        module     as ''Module'',',
'        client_id  as ''Client Identifier'',',
'        action     as ''Action'',',
'        ip         as ''IP Address'',',
'        host       as ''Host'',',
'        os_user    as ''OS User'',',
'        app_user   as ''App User'',',
'        schema     as ''Schema''',
'    )',
')'))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>2540130677583398057
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_no_data_found=>'No context recorded.'
,p_csv_output=>'N'
