 p_id=>wwv_flow_imp.id(5527596059561022)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Purge Errors'
,p_static_id=>'purge-errors'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_deleted number;',
'begin',
'    util_audit.purge_errors(',
'        p_before         => cast(to_date(:P8_ERRORS_BEFORE, ''YYYY-MM-DD'') as timestamp),',
'        p_errors_deleted => l_deleted',
'    );',
'    apex_application.g_print_success_message := l_deleted || '' error(s) deleted.'';',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(5527032888561021)
,p_internal_uid=>5527596059561022
