,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Purge History'
,p_static_id=>'purge-history'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_deleted number;',
'begin',
'    util_audit.purge(',
'        p_before         => cast(to_date(:P8_PURGE_BEFORE, ''YYYY-MM-DD'') as timestamp),',
'        p_table_name     => :P8_PURGE_TABLE,',
'        p_events_deleted => l_deleted',
'    );',
'    apex_application.g_print_success_message := l_deleted || '' audit event(s) deleted.'';',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(5526994488561021)
