'    ';
wwv_flow_imp.g_varchar2_table(17) := '    p_table_name IN VARCHAR2'||wwv_flow.LF||
'    ) RETURN BOOLEAN;'||wwv_flow.LF||
''||wwv_flow.LF||
'    FUNCTION table_enabled_sql ('||wwv_flow.LF||
'        p_table';
wwv_flow_imp.g_varchar2_table(18) := '_name IN VARCHAR2'||wwv_flow.LF||
'    ) RETURN VARCHAR2;'||wwv_flow.LF||
''||wwv_flow.LF||
'    ------------------------------------------------------';
wwv_flow_imp.g_varchar2_table(19) := '------------------------'||wwv_flow.LF||
'    -- CONTEXT'||wwv_flow.LF||
