''||wwv_flow.LF||
'    -------------------';
wwv_flow_imp.g_varchar2_table(21) := '-----------------------------------------------------------'||wwv_flow.LF||
'    -- CAPTURE (called by triggers)'||wwv_flow.LF||
'    ';
wwv_flow_imp.g_varchar2_table(22) := '------------------------------------------------------------------------------'||wwv_flow.LF||
''||wwv_flow.LF||
'    PROCEDURE captur';
wwv_flow_imp.g_varchar2_table(23) := 'e_audit ('||wwv_flow.LF||
'        p_transaction_json IN json_object_t'||wwv_flow.LF||
'    );'||wwv_flow.LF||
''||wwv_flow.LF||
'    -- Records an audit failure in UTI';
wwv_flow_imp.g_varchar2_table(24) := 'L_AUDIT_ERRORS (autonomous transaction).'||wwv_flow.LF||
'    -- Never raises.'||wwv_flow.LF||
'    PROCEDURE log_error ('||wwv_flow.LF||
'        p_ta';
wwv_flow_imp.g_varchar2_table(25) := 'ble_name       IN VARCHAR2,'||wwv_flow.LF||
'        p_transaction_type IN VARCHAR2,'||wwv_flow.LF||
'        p_pk_value         IN VA';
wwv_flow_imp.g_varchar2_table(26) := 'RCHAR2,'||wwv_flow.LF||
'        p_error_code       IN NUMBER,'||wwv_flow.LF||
'        p_error_message    IN VARCHAR2,'||wwv_flow.LF||
'        p_erro';
wwv_flow_imp.g_varchar2_table(27) := 'r_backtrace  IN VARCHAR2'||wwv_flow.LF||
'    );'||wwv_flow.LF||
''||wwv_flow.LF||
'    ---------------------------------------------------------------';
wwv_flow_imp.g_varchar2_table(28) := '---------------'||wwv_flow.LF||
'    -- PURGE'||wwv_flow.LF||
'    -------------------------------------------------------------------';
wwv_flow_imp.g_varchar2_table(29) := '-----------'||wwv_flow.LF||
''||wwv_flow.LF||
'    -- Deletes audit events (and their column changes) older than p_before.'||wwv_flow.LF||
'    -- p_ta';
wwv_flow_imp.g_varchar2_table(30) := 'ble_name limits the purge to one table. Does not commit.'||wwv_flow.LF||
'    PROCEDURE purge ('||wwv_flow.LF||
'        p_before     ';
wwv_flow_imp.g_varchar2_table(31) := '    IN  TIMESTAMP,'||wwv_flow.LF||
'        p_table_name     IN  VARCHAR2 DEFAULT NULL,'||wwv_flow.LF||
'        p_events_deleted OUT ';
wwv_flow_imp.g_varchar2_table(32) := 'NUMBER'||wwv_flow.LF||
'    );'||wwv_flow.LF||
''||wwv_flow.LF||
'    -- Deletes logged audit errors older than p_before. Does not commit.'||wwv_flow.LF||
'    PROCEDUR';
wwv_flow_imp.g_varchar2_table(33) := 'E purge_errors ('||wwv_flow.LF||
'        p_before         IN  TIMESTAMP,'||wwv_flow.LF||
'        p_errors_deleted OUT NUMBER'||wwv_flow.LF||
'    );'||wwv_flow.LF||
'';
wwv_flow_imp.g_varchar2_table(34) := ''||wwv_flow.LF||
'    ------------------------------------------------------------------------------'||wwv_flow.LF||
'    -- RESTORE'||wwv_flow.LF||
' ';
wwv_flow_imp.g_varchar2_table(35) := '   ------------------------------------------------------------------------------'||wwv_flow.LF||
''||wwv_flow.LF||
'    -- Puts a row';
wwv_flow_imp.g_varchar2_table(36) := ' back the way it was just before one audited event.'||wwv_flow.LF||
'    --   DELETE event: re-inserts the row.'||wwv_flow.LF||
'    -';
wwv_flow_imp.g_varchar2_table(37) := '-   UPDATE event: sets the row''s columns back to their old values.'||wwv_flow.LF||
'    --   INSERT events cannot be ';
wwv_flow_imp.g_varchar2_table(38) := 'restored.'||wwv_flow.LF||
'    --'||wwv_flow.LF||
'    -- p_include_children: also restore child rows (found through foreign keys)'||wwv_flow.LF||
'   ';
wwv_flow_imp.g_varchar2_table(39) := ' --     that were deleted, or had their FK set to NULL, in the same database'||wwv_flow.LF||
'    --     transaction ';
wwv_flow_imp.g_varchar2_table(40) := 'as a restored DELETE. Grandchildren are included.'||wwv_flow.LF||
'    -- p_force:   restore even when the row has la';
wwv_flow_imp.g_varchar2_table(41) := 'ter audit events, which'||wwv_flow.LF||
'    --            overwrites those later changes.'||wwv_flow.LF||
'    -- p_preview: do the f';
wwv_flow_imp.g_varchar2_table(42) := 'ull restore, print what happened, then roll it back.'||wwv_flow.LF||
'    --'||wwv_flow.LF||
'    -- Does not commit. Prints each step';
wwv_flow_imp.g_varchar2_table(43) := ' with DBMS_OUTPUT. On error, everything'||wwv_flow.LF||
'    -- this call changed is rolled back.'||wwv_flow.LF||
'    PROCEDURE resto';
wwv_flow_imp.g_varchar2_table(44) := 're_row ('||wwv_flow.LF||
'        p_transaction_id   IN VARCHAR2,'||wwv_flow.LF||
'        p_include_children IN BOOLEAN DEFAULT TRUE,';
wwv_flow_imp.g_varchar2_table(45) := ''||wwv_flow.LF||
'        p_force            IN BOOLEAN DEFAULT FALSE,'||wwv_flow.LF||
'        p_preview          IN BOOLEAN DEFAULT ';
wwv_flow_imp.g_varchar2_table(46) := 'FALSE'||wwv_flow.LF||
'    );'||wwv_flow.LF||
''||wwv_flow.LF||
'END util_audit;'||wwv_flow.LF||
'/';
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(5508043693560917)
,p_install_id=>wwv_flow_imp.id(5507751401560914)
,p_name=>'install-util-audit-spec'
,p_sequence=>30
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_imp.varchar2_to_clob(wwv_flow_imp.g_varchar2_table)
);
end;
